function sculpt(sections){const p=[],ix=[],n=24;for(let j=0;j<sections.length;j++){let [z,y,rx,ry]=sections[j];for(let i=0;i<n;i++){let a=i/n*Math.PI*2,r=1+Math.sin(i*5+j*3)*.012;p.push(Math.cos(a)*rx*r,y+Math.sin(a)*ry*r,z);}}for(let j=0;j<sections.length-1;j++)for(let i=0;i<n;i++){let a=j*n+i,b=j*n+(i+1)%n,c=a+n,d=b+n;ix.push(a,b,c,b,d,c);}const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.Float32BufferAttribute(p,3));geo.setIndex(ix);geo.computeVertexNormals();return geo;}
