function renderTree(){$('#bank').textContent=state.sun;$('#branches').innerHTML=branchNames.map((n,b)=>`<div class="branch"><div class="icon">${branchIcons[b]}</div><h3>${n}</h3><div class="nodes">${Array.from({length:6},(_,i)=>`<span class="node ${i<state.levels[b]?'on':''}"></span>`).join('')}</div><p>${upgrades[b][Math.min(5,state.levels[b])]}</p><button data-buy="${b}" ${state.levels[b]>=6||state.sun<cost(b)?'disabled':''}>${state.levels[b]>=6?'Flourishing':'✧ '+cost(b)+' · Grow'}</button></div>`).join('');document.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>upgrade(+b.dataset.buy));}
